import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.DlhmXL2o.js";const m=JSON.parse('{"title":"Two styles, one engine","description":"","frontmatter":{},"headers":[],"relativePath":"learn/explanation/two-styles.md","filePath":"learn/explanation/two-styles.md","lastUpdated":1786512376000}'),n={name:"learn/explanation/two-styles.md"};function r(i,e,d,c,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="two-styles-one-engine" tabindex="-1">Two styles, one engine <a class="header-anchor" href="#two-styles-one-engine" aria-label="Permalink to &quot;Two styles, one engine&quot;">​</a></h1><p>Argot lets you declare a command line two ways: Kotlin delegates, or annotations on a <code>data class</code> with a parser generated by KSP. Libraries that offer two front ends usually end up with two behaviours, because each front end grows its own parsing code and the two drift. Argot avoids that by structure rather than by care.</p><h2 id="where-the-two-paths-meet" tabindex="-1">Where the two paths meet <a class="header-anchor" href="#where-the-two-paths-meet" aria-label="Permalink to &quot;Where the two paths meet&quot;">​</a></h2><p>Both styles converge on one type before any parsing happens:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes argot-light argot-dark vp-code" tabindex="0"><code><span class="line"><span>delegates ─────┐</span></span>
<span class="line"><span>               ├──▶ CommandSpec ──▶ ArgotEngine ──▶ ParsedValues</span></span>
<span class="line"><span>annotations ───┘</span></span></code></pre></div><p><code>CommandSpec</code> is the whole description of a command: its name, its description, and the options, flags and positionals it accepts. Delegates build one as you read properties. The generated parser builds one in its <code>init</code>. Neither contains parsing logic — they only describe.</p><p>Everything a user can observe happens <em>after</em> that meeting point. <code>ArgotEngine</code> does all the tokenising, matching, conversion and error reporting. <code>CommandSpec.renderHelp</code> produces the entire <code>--help</code> screen. Both styles reach the same code because there is only one copy of it.</p><h2 id="why-this-matters-more-than-it-sounds" tabindex="-1">Why this matters more than it sounds <a class="header-anchor" href="#why-this-matters-more-than-it-sounds" aria-label="Permalink to &quot;Why this matters more than it sounds&quot;">​</a></h2><p>Two implementations would not diverge on the obvious things — everyone remembers that <code>--name Ada</code> sets <code>name</code>. They diverge on the edges: whether <code>--count=2</code> is accepted alongside <code>--count 2</code>, whether a repeated single-valued option is an error or a silent overwrite, exactly how a converter failure is worded, how many spaces separate a flag from its help text.</p><p>Those are the details your own tests will assert on. With one engine, there is nothing that could disagree.</p><h2 id="what-the-processor-is-and-is-not" tabindex="-1">What the processor is, and is not <a class="header-anchor" href="#what-the-processor-is-and-is-not" aria-label="Permalink to &quot;What the processor is, and is not&quot;">​</a></h2><p>The KSP processor is not a parser. It reads your annotated constructor, resolves each parameter&#39;s type to a converter, and emits a function that builds a <code>CommandSpec</code>, calls <code>ArgotEngine</code>, and hands the results to your constructor. It is a transcription step, not a second implementation.</p><p>That is also why the processor never reaches your runtime classpath. Its entire output is ordinary Kotlin calling <code>argot-core</code>.</p><h2 id="what-this-means-for-mixing-versions" tabindex="-1">What this means for mixing versions <a class="header-anchor" href="#what-this-means-for-mixing-versions" aria-label="Permalink to &quot;What this means for mixing versions&quot;">​</a></h2><p>Because generated code calls <code>CommandSpec</code>, the <code>ParamSpec</code> constructors, <code>ArgotEngine.parse</code> and the <code>ParsedValues</code> accessors directly, those declarations are a public contract even though nobody types them. You can end up with <code>argot-processor</code> from one version and <code>argot-core</code> from another in the same build — a transitive dependency is enough — and code emitted by the older processor still has to compile against the newer core.</p><p>Argot therefore treats that set of declarations as a versioned surface in its own right. See <a href="./breaking-changes">what counts as a breaking change</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../how-to/choosing-a-style">Choose between the delegate and annotation styles</a> for the practical differences that remain.</li><li><a href="/docs/dev/api/org.draftcode.argot/CommandSpec"><code>CommandSpec</code></a> and <a href="/docs/dev/api/org.draftcode.argot/ArgotEngine"><code>ArgotEngine</code></a>.</li></ul>`,18)])])}const g=a(n,[["render",r]]);export{m as __pageData,g as default};
